<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../app/helpers.php';require_role('admin');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim((string)($_POST['username']??''));$name=trim((string)($_POST['full_name']??''));$password=(string)($_POST['password']??'');$role=$_POST['role']??'staff';if(!preg_match('/^[a-zA-Z0-9_.-]{3,40}$/',$username)||$name===''||strlen($password)<8||!in_array($role,['admin','staff'],true)){flash('danger','Tên đăng nhập 3–40 ký tự; mật khẩu ít nhất 8 ký tự; kiểm tra vai trò.');redirect('/users.php');}try{$st=$pdo->prepare('INSERT INTO users(username,password_hash,full_name,role) VALUES(?,?,?,?)');$st->execute([$username,password_hash($password,PASSWORD_DEFAULT),$name,$role]);flash('success','Đã tạo tài khoản.');}catch(PDOException $e){flash('danger','Tên đăng nhập đã tồn tại hoặc dữ liệu không hợp lệ.');}redirect('/users.php');}
$rows=$pdo->query('SELECT id,username,full_name,role,is_active,created_at FROM users ORDER BY id')->fetchAll();$pageTitle='Tài khoản';require __DIR__.'/../app/layout/header.php';?>
<div class="page-heading mb-3"><div><h1 class="h3">Quản lý tài khoản</h1><p class="text-secondary mb-0">Chỉ Admin được tạo tài khoản mới.</p></div></div><div class="row g-4"><div class="col-12 col-lg-4"><div class="card"><div class="card-body"><h2 class="h5">Tạo tài khoản</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Tên đăng nhập</label><input name="username" class="form-control" minlength="3" maxlength="40" required></div><div class="mb-3"><label class="form-label">Họ tên</label><input name="full_name" class="form-control" required></div><div class="mb-3"><label class="form-label">Mật khẩu (ít nhất 8 ký tự)</label><input type="password" name="password" class="form-control" minlength="8" required></div><div class="mb-3"><label class="form-label">Vai trò</label><select name="role" class="form-select"><option value="staff">Nhân viên</option><option value="admin">Admin</option></select></div><button class="btn btn-primary">Tạo tài khoản</button></form></div></div></div><div class="col-12 col-lg-8"><div class="card"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Username</th><th>Họ tên</th><th>Vai trò</th><th>Ngày tạo</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['full_name'])?></td><td><span class="badge text-bg-<?=$u['role']==='admin'?'primary':'secondary'?>"><?=e($u['role'])?></span></td><td><?=e(date('d/m/Y',strtotime($u['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require __DIR__.'/../app/layout/footer.php';?>
